507: func sanitize(value string) string {
508: 	value = strings.ReplaceAll(value, "/", "-")
509: 	value = strings.ReplaceAll(value, ".", "-")
510: 	value = strings.ReplaceAll(value, " ", "-")
511: 	return value
512: }
