365: func workspaceHasLargeFile(root string) bool {
366: 	found := false
367: 	_ = filepath.WalkDir(root, func(path string, entry os.DirEntry, err error) error {
368: 		if err != nil || entry.IsDir() {
369: 			return nil
370: 		}
371: 		data, err := os.ReadFile(path)
372: 		if err != nil || len(data) > 1<<20 {
373: 			return nil
374: 		}
375: 		if strings.Count(string(data), "\n")+1 > 700 {
376: 			found = true
377: 		}
378: 		return nil
379: 	})
380: 	return found
381: }
