383: // prepareWorkspace creates an isolated directory and writes the task baseline into it.
384: func prepareWorkspace(root, id string, task Task) (string, error) {
385: 	dir := filepath.Join(root, id)
386: 	if err := os.MkdirAll(dir, 0o755); err != nil {
387: 		return "", err
388: 	}
389: 	names := make([]string, 0, len(task.Files))
390: 	for name := range task.Files {
391: 		names = append(names, name)
392: 	}
393: 	sort.Strings(names)
394: 	for _, name := range names {
395: 		path := filepath.Join(dir, name)
396: 		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
397: 			return "", err
398: 		}
399: 		if err := os.WriteFile(path, []byte(task.Files[name]), 0o644); err != nil {
400: 			return "", err
401: 		}
402: 	}
403: 	return dir, nil
404: }
